function renderPreferences(): void { ?>
<div class="theme-toggle" role="group" aria-label="Colour theme">
<?php foreach(['light'=>'Light','dark'=>'Dark','system'=>'System'] as $key=>$label):?><button type="button" data-theme="<?=$key?>" aria-pressed="false" aria-label="<?=$label?> theme" title="<?=$label?> theme"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><?php if($key==='light'):?><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/><?php elseif($key==='dark'):?><path d="M20.8 13A9 9 0 0 1 11 3.2 9 9 0 1 0 20.8 13Z"/><?php else:?><rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/><?php endif;?></svg></button><?php endforeach;?></div>
<div class="language-flags" role="group" aria-label="Language"><?php foreach([['en','English','gb'],['fr','Français','fr'],['rw','Kinyarwanda','rw']] as [$code,$label,$flag]):?><button type="button" data-language="<?=$code?>" aria-label="<?=$label?>" title="<?=$label?>" aria-pressed="false"><img src="/flags/<?=$flag?>.svg" alt="" width="24" height="16"></button><?php endforeach;?></div>
