function renderFooter(array $site,array $cats): void { ?>
<footer id="contact" class="refined-footer">
<div class="wrap footer-invitation"><div><span class="footer-kicker">LET'S BUILD SOMETHING BETTER</span><h2>Find the right products for your next project.</h2><p><?=copyText($site,'footer.connectBody')?></p></div><a class="footer-project-link" href="/quote"><?=copyText($site,'footer.quote')?> <span aria-hidden="true">→</span></a></div>
<div class="wrap foot-grid"><section class="foot-brand"><a href="/" aria-label="MATTE home"><img src="<?=e($site['branding']['lightLogoUrl']??'/brand/logo-light.png')?>" alt="MATTE" width="156" height="44"></a><p class="foot-note"><?=copyText($site,'footer.tagline')?></p><p class="footer-reach">Serving Africa, especially Rwanda.</p><a class="foot-link" href="/about"><?=copyText($site,'footer.aboutLink')?></a></section>
<section><h3>Explore our departments</h3><ul><?php foreach(departmentChildren($cats) as $c):?><li><a href="/products?category=<?=e($c['slug'])?>"><?=e($c['name'])?></a></li><?php endforeach;?></ul><a class="foot-link footer-shop-all" href="/products"><?=copyText($site,'footer.shopAll')?> →</a></section>
<section><h3>Your MATTE account</h3><ul><?php foreach(['/account'=>'Profile & orders','/cart'=>'Shopping cart','/signin'=>'Sign in','/signup'=>'Create an account','/quote'=>'Product & project enquiries'] as $href=>$label):?><li><a href="<?=$href?>"><?=e($label)?></a></li><?php endforeach;?></ul></section>
<section class="footer-contact"><h3><?=copyText($site,'footer.contactTitle')?></h3><div class="footer-contact-item"><span>CALL OUR TEAM</span><?php foreach(['phone1','phone2'] as $phone):if(empty($site['footer'][$phone]))continue;?><a href="tel:<?=e(preg_replace('/[^+0-9]/','',$site['footer'][$phone]))?>"><?=copyText($site,'footer.'.$phone)?></a><?php endforeach;?></div><div class="footer-contact-item"><span>EMAIL</span><a href="mailto:<?=e($site['footer']['email'])?>"><?=copyText($site,'footer.email')?></a></div><div class="footer-contact-item"><span>OUR LOCATION</span><p><?=copyText($site,'footer.address')?></p></div></section></div>
<div class="foot-bottom"><div class="wrap foot-base"><span>© <?=date('Y')?> <?=copyText($site,'footer.copyright')?></span><div class="footer-bottom-links"><a href="/about">About MATTE</a><a href="/quote">Contact our team</a></div></div></div>
</footer>
<?php }
